import mq3.game.rankings as r
function req(ok,label) if not ok then return error(7462,"game rankings: "+label) end if;return 1 end function
function reset(s) s.reports=[];return void end function
function main(args)
  count=0;s=r.create(3);s.clients[0].team=1;s.clients[1].team=2;s.clients[2].team=1
  r.G_RankFireWeapon(s,0,r.WP_ROCKET_LAUNCHER);count=count+req(len(s.reports)==2 and s.reports[0].key==r.QGR_KEY_SHOT_FIRED and s.reports[1].key==1111020502,"rocket fire");reset(s);r.G_RankFireWeapon(s,0,r.WP_GAUNTLET);count=count+req(len(s.reports)==0,"gauntlet fire deferred")
  s.framenum=1;r.G_RankDamage(s,0,1,20,r.MOD_SHOTGUN);count=count+req(len(s.reports)==8 and s.reports[0].key==r.QGR_KEY_HIT_TAKEN,"damage taken and given");r.G_RankDamage(s,0,1,10,r.MOD_SHOTGUN);count=count+req(len(s.reports)==12,"same-frame pellet suppresses hits")
  reset(s);s.framenum=2;r.G_RankDamage(s,0,2,40,r.MOD_ROCKET_SPLASH);count=count+req(len(s.reports)==18 and s.reports[len(s.reports)-1].key==r.QGR_KEY_TEAMMATE_SPLASH_GIVEN,"friendly splash")
  reset(s);r.G_RankDamage(s,0,r.ENTITYNUM_WORLD,5,r.MOD_LAVA);count=count+req(len(s.reports)==0,"hazard damage ignored")
  r.G_RankPlayerDie(s,0,r.ENTITYNUM_WORLD,r.MOD_LAVA);count=count+req(s.reports[0].key==r.QGR_KEY_HAZARD_DEATH and s.reports[1].key==1111080300,"hazard death");reset(s);r.G_RankPlayerDie(s,0,0,r.MOD_ROCKET_SPLASH);count=count+req(s.reports[1].key==1111020501,"weapon suicide");reset(s);r.G_RankPlayerDie(s,0,1,r.MOD_RAILGUN);count=count+req(s.reports[0].index1==1 and s.reports[0].index2==0 and s.reports[1].key==1211020700,"rail frag")
  reset(s);s.time=5500;s.clients[0].weaponChangeTime=1000;r.G_RankWeaponTime(s,0,r.WP_LIGHTNING);count=count+req(s.reports[0].value==4 and s.reports[1].key==1111020810,"weapon time")
  reset(s);r.G_RankPickupWeapon(s,0,r.WP_PLASMAGUN);count=count+req(s.reports[1].key==1111020609,"weapon pickup");reset(s);r.G_RankPickupAmmo(s,0,r.WP_RAILGUN,10);count=count+req(len(s.reports)==4 and s.reports[3].key==1111030601,"ammo pickup");reset(s);r.G_RankPickupHealth(s,0,100);count=count+req(s.reports[2].key==1111040400,"mega health");reset(s);r.G_RankPickupArmor(s,0,50);count=count+req(s.reports[2].key==1111050200,"yellow armor")
  reset(s);r.G_RankPickupPowerup(s,0,r.PW_REDFLAG);count=count+req(len(s.reports)==1 and s.reports[0].key==r.QGR_KEY_FLAG_PICKUP,"flag pickup");reset(s);r.G_RankPickupPowerup(s,0,r.PW_REGEN);count=count+req(s.reports[1].key==1111060500,"regen pickup");reset(s);r.G_RankPickupHoldable(s,0,r.HI_MEDKIT);r.G_RankUseHoldable(s,0,r.HI_MEDKIT);count=count+req(s.reports[0].key==r.QGR_KEY_MEDKIT and s.reports[1].key==r.QGR_KEY_MEDKIT_USE,"holdable")
  reset(s);r.G_RankReward(s,0,r.EF_AWARD_IMPRESSIVE);r.G_RankCapture(s,0);r.G_RankUserTeamName(s,0,"Red");count=count+req(s.reports[0].key==1111090000 and s.reports[1].key==r.QGR_KEY_FLAG_CAPTURE and s.reports[2].text=="Red","reward capture team")
  reset(s);s.time=120000;s.clients[0].enterTime=0;s.clients[0].matchRating=600;r.G_RankClientDisconnect(s,0);count=count+req(s.reports[0].value==5 and not s.reports[0].accum,"match rating")
  s=r.create(2);s.active=true;s.gametype=0;s.clients[0].status=r.QGR_STATUS_ACTIVE;s.clients[0].team=r.TEAM_SPECTATOR;s.clients[1].bot=true;s.clients[1].name="Bot";s.fraglimit=0;s.timelimit=0;s.time=5000;r.G_RankRunFrame(s);count=count+req(s.clients[0].team==0 and s.timelimit==1000 and s.clients[0].matchTime==5,"rank frame policy");count=count+req(s.actions[0].kind=="set-team" and s.actions[len(s.actions)-1].text=="kick Bot\n","active and bot handling")
  reset(s);s.clients[0].matchRating=0;s.clients[0].enterTime=0;s.time=60000;s.cvars=[["sv_hostname","Host"],["mapname","q3dm1"],["fs_game",""],["sv_maxRate","25000"],["sv_minPing","0"],["sv_maxPing","0"],["dedicated","1"],["version","Q3 1.32"]];r.G_RankGameOver(s);count=count+req(len(s.reports)==13 and s.reports[1].text=="Host" and s.reports[len(s.reports)-1].text=="Q3 1.32","game over metadata")
  warm=r.create(1);warm.warmupTime=1;r.G_RankPickupHealth(warm,0,25);r.G_RankPlayerDie(warm,0,0,r.MOD_ROCKET);count=count+req(len(warm.reports)==0,"warmup suppression")
  print("PASS: "+str(count)+" game ranking contracts");return 0
end function
